import React, { useState, useEffect } from 'react';
import { StyleSheet, Text, View, TextInput, TouchableOpacity, Alert, ActivityIndicator, ScrollView } from 'react-native';
import * as DocumentPicker from 'expo-document-picker';
import * as FileSystem from 'expo-file-system';
import HttpBridge from 'react-native-http-bridge-refactored';
import { NetworkInfo } from 'react-native-network-info';

export default function App() {
  const [ps4Ip, setPs4Ip] = useState('');
    const [localIp, setLocalIp] = useState('');
      const [selectedFile, setSelectedFile] = useState(null);
        const [isServerRunning, setIsServerRunning] = useState(false);
          const [statusText, setStatusText] = useState('Listo para seleccionar PKG');
            const [loading, setLoading] = useState(false);

              const PORT = 8080;

                useEffect(() => {
                    // Obtener la IP local del móvil en la red Wi-Fi
                        NetworkInfo.getIPV4Address().then(ip => {
                              setLocalIp(ip || 'No detectada');
                                  });

                                      return () => {
                                            HttpBridge.stop();
                                                };
                                                  }, []);

                                                    // 1. Iniciar servidor HTTP en el móvil
                                                      const startHttpServer = async (filePath) => {
                                                          try {
                                                                HttpBridge.stop(); // Detener si había uno activo
                                                                      HttpBridge.start(PORT, 'http_service', (request) => {
                                                                              if (request.type === 'GET') {
                                                                                        HttpBridge.respond(request.requestId, 200, 'application/octet-stream', filePath);
                                                                                                }
                                                                                                      });
                                                                                                            setIsServerRunning(true);
                                                                                                                  return true;
                                                                                                                      } catch (err) {
                                                                                                                            Alert.alert('Error', 'No se pudo iniciar el servidor HTTP local en el móvil.');
                                                                                                                                  return false;
                                                                                                                                      }
                                                                                                                                        };

                                                                                                                                          // 2. Seleccionar archivo PKG del almacenamiento del móvil
                                                                                                                                            const pickPkgFile = async () => {
                                                                                                                                                try {
                                                                                                                                                      const res = await DocumentPicker.getDocumentAsync({
                                                                                                                                                              type: '*/*',
                                                                                                                                                                      copyToCacheDirectory: false,
                                                                                                                                                                            });

                                                                                                                                                                                  if (!res.canceled && res.assets && res.assets.length > 0) {
                                                                                                                                                                                          const file = res.assets[0];
                                                                                                                                                                                                  if (!file.name.endsWith('.pkg')) {
                                                                                                                                                                                                            Alert.alert('Archivo no válido', 'Por favor selecciona un archivo con extensión .pkg');
                                                                                                                                                                                                                      return;
                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                      setSelectedFile(file);
                                                                                                                                                                                                                                              setStatusText(`Seleccionado: ${file.name}`);
                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                        } catch (err) {
                                                                                                                                                                                                                                                              Alert.alert('Error', 'No se pudo acceder al archivo.');
                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                    };

                                                                                                                                                                                                                                                                      // 3. Enviar orden de instalación a la PS4
                                                                                                                                                                                                                                                                        const sendToPs4 = async () => {
                                                                                                                                                                                                                                                                            if (!ps4Ip) {
                                                                                                                                                                                                                                                                                  Alert.alert('Falta la IP', 'Ingresa la dirección IP de tu PS4.');
                                                                                                                                                                                                                                                                                        return;
                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                if (!selectedFile) {
                                                                                                                                                                                                                                                                                                      Alert.alert('Falta el juego', 'Selecciona un archivo .pkg primero.');
                                                                                                                                                                                                                                                                                                            return;
                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                    setLoading(true);
                                                                                                                                                                                                                                                                                                                        setStatusText('Iniciando servidor local...');

                                                                                                                                                                                                                                                                                                                            const serverOk = await startHttpServer(selectedFile.uri);
                                                                                                                                                                                                                                                                                                                                if (!serverOk) {
                                                                                                                                                                                                                                                                                                                                      setLoading(false);
                                                                                                                                                                                                                                                                                                                                            return;
                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                    const pkgUrl = `http://${localIp}:${PORT}/${encodeURIComponent(selectedFile.name)}`;
                                                                                                                                                                                                                                                                                                                                                        setStatusText('Enviando orden a la PS4...');

                                                                                                                                                                                                                                                                                                                                                            try {
                                                                                                                                                                                                                                                                                                                                                                  // Petición a la API de Remote PKG Installer en la PS4 (puerto 12800)
                                                                                                                                                                                                                                                                                                                                                                        const response = await fetch(`http://${ps4Ip}:12800/api/install`, {
                                                                                                                                                                                                                                                                                                                                                                                method: 'POST',
                                                                                                                                                                                                                                                                                                                                                                                        headers: { 'Content-Type': 'application/json' },
                                                                                                                                                                                                                                                                                                                                                                                                body: JSON.stringify({
                                                                                                                                                                                                                                                                                                                                                                                                          type: 'direct',
                                                                                                                                                                                                                                                                                                                                                                                                                    packages: [pkgUrl]
                                                                                                                                                                                                                                                                                                                                                                                                                            })
                                                                                                                                                                                                                                                                                                                                                                                                                                  });

                                                                                                                                                                                                                                                                                                                                                                                                                                        const data = await response.json();

                                                                                                                                                                                                                                                                                                                                                                                                                                              if (data.status === 'success') {
                                                                                                                                                                                                                                                                                                                                                                                                                                                      setStatusText('¡Instalación iniciada con éxito en la PS4!');
                                                                                                                                                                                                                                                                                                                                                                                                                                                              Alert.alert('¡Éxito!', 'El juego ha comenzado a instalarse en tu PS4.');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            setStatusText('La PS4 rechazó la instalación.');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    Alert.alert('Error PS4', data.message || 'Respuesta de error desde la PS4.');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              } catch (err) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    setStatusText('Error de conexión con la PS4.');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          Alert.alert('Error de conexión', 'No se pudo contactar a la PS4. Verifica que la app Remote PKG Installer / GoldHEN esté abierta en la PS4 y compartan la misma red Wi-Fi.');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              } finally {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    setLoading(false);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <ScrollView contentContainerStyle={styles.container}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <Text style={styles.title}>PS4 PKG Sender Mobile</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <Text style={styles.subtitle}>Instala PKGs desde tu móvil</Text>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <View style={styles.card}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <Text style={styles.label}>IP de tu Móvil (Wi-Fi):</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <Text style={styles.ipText}>{localIp}</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </View>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <View style={styles.card}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <Text style={styles.label}>Dirección IP de la PS4:</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <TextInput
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        style={styles.input}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  placeholder="Ej: 192.168.1.15"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            placeholderTextColor="#777"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      value={ps4Ip}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                onChangeText={setPs4Ip}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          keyboardType="numeric"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </View>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <TouchableOpacity style={styles.fileButton} onPress={pickPkgFile}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <Text style={styles.fileButtonText}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {selectedFile ? `📄 ${selectedFile.name}` : '📁 Seleccionar archivo .pkg'}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </TouchableOpacity>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <TouchableOpacity
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            style={[styles.installButton, loading && styles.disabledButton]}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    onPress={sendToPs4}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            disabled={loading}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          {loading ? (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <ActivityIndicator color="#fff" />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ) : (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <Text style={styles.installButtonText}>🚀 INSTALAR EN PS4</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </TouchableOpacity>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <View style={styles.statusBox}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <Text style={styles.statusTitle}>Estado:</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <Text style={styles.statusContent}>{statusText}</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </ScrollView>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const styles = StyleSheet.stylesheet ? StyleSheet.stylesheet : {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        container: { flexGrow: 1, backgroundColor: '#0b0e14', padding: 20, justifyContent: 'center' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          title: { fontSize: 26, fontWeight: 'bold', color: '#0072CE', textAlign: 'center' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            subtitle: { fontSize: 14, color: '#aaa', textAlign: 'center', marginBottom: 25 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              card: { backgroundColor: '#161b22', padding: 15, borderRadius: 10, marginBottom: 15, borderWidth: 1, borderColor: '#21262d' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                label: { color: '#8b949e', fontSize: 12, marginBottom: 5 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ipText: { color: '#58a6ff', fontSize: 16, fontWeight: '600' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    input: { color: '#fff', fontSize: 16, paddingVertical: 5 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      fileButton: { backgroundColor: '#21262d', padding: 16, borderRadius: 10, alignItems: 'center', marginBottom: 15, borderWidth: 1, borderColor: '#30363d' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        fileButtonText: { color: '#58a6ff', fontWeight: 'bold', fontSize: 15 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          installButton: { backgroundColor: '#0072CE', padding: 18, borderRadius: 10, alignItems: 'center', marginBottom: 20 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            disabledButton: { opacity: 0.6 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              installButtonText: { color: '#fff', fontWeight: 'bold', fontSize: 16 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                statusBox: { backgroundColor: '#161b22', padding: 15, borderRadius: 10, borderWidth: 1, borderColor: '#30363d' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  statusTitle: { color: '#8b949e', fontSize: 12 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    statusContent: { color: '#e6edf3', fontSize: 14, marginTop: 4 }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    };